import 'dart:convert';

import 'package:cryptography/cryptography.dart';
import 'package:flutter_test/flutter_test.dart';

/// Article 7.6 — the signature, verified against bytes the **server** produced.
///
/// The fixture below was generated by running Python's `cryptography` through the
/// exact code path `apps/common/signing.py` uses: the same canonicalisation, the
/// same Ed25519, the same hex encoding. That matters more than it sounds. A test
/// that signs and verifies inside Dart proves only that Dart agrees with itself,
/// and the failure this guards against is precisely the two languages disagreeing
/// — most likely about canonicalisation, where a single space or a sorted-key
/// difference silently invalidates every real snapshot.
///
/// `signing.py` calls `canonical_bytes` a protocol contract and versions the
/// payload rather than editing it. This test is the other half of that contract,
/// written down on the side that consumes it.
void main() {
  // Generated 2026-08-21 with a throwaway key. The private half was never
  // written down — only the app's side of the exchange is being tested here.
  const publicKeyHex =
      'cf7eaf96d8be275f82a767809ce2c0fdba498e9b9ab7217186ce8be4e1674720';
  const signatureHex =
      '7d2d897c75968a5117ff6730f29b27f123638ac53a103e9eef01d1cce5f082d4'
      'fb120cb75c72471625d81a911a4963e30b092d30bc5f220d6c14361cfea6510d';
  const canonical =
      '{"ends_at_ms":1775725200000,"grace_ends_at_ms":1775984400000,'
      '"issued_at_ms":1773133200000,"parent_id":7,"plan":"monthly",'
      '"started_at_ms":1773133200000,"state":"active","version":1}';

  final payload = <String, dynamic>{
    'version': 1,
    'parent_id': 7,
    'state': 'active',
    'plan': 'monthly',
    'started_at_ms': 1773133200000,
    'ends_at_ms': 1775725200000,
    'grace_ends_at_ms': 1775984400000,
    'issued_at_ms': 1773133200000,
  };

  /// The same rule as `SubscriptionRepository._canonical`, kept here so the test
  /// exercises the rule rather than the class's private copy of it.
  String canonicalise(Map<String, dynamic> input) {
    final keys = input.keys.toList()..sort();
    final buffer = StringBuffer('{');
    for (var i = 0; i < keys.length; i++) {
      if (i > 0) buffer.write(',');
      buffer
        ..write(jsonEncode(keys[i]))
        ..write(':')
        ..write(jsonEncode(input[keys[i]]));
    }
    buffer.write('}');
    return buffer.toString();
  }

  Future<bool> verify(String body, String signature, String key) async {
    List<int> hex(String s) => [
          for (var i = 0; i < s.length; i += 2)
            int.parse(s.substring(i, i + 2), radix: 16),
        ];
    return Ed25519().verify(
      utf8.encode(body),
      signature: Signature(
        hex(signature),
        publicKey: SimplePublicKey(hex(key), type: KeyPairType.ed25519),
      ),
    );
  }

  test('Dart canonicalises exactly as the server does', () {
    expect(canonicalise(payload), canonical,
        reason: 'sorted keys, no whitespace, UTF-8. A single space here '
            'invalidates every snapshot the server has ever signed.');
  });

  test('a snapshot signed by the server verifies in the app', () async {
    expect(await verify(canonical, signatureHex, publicKeyHex), isTrue);
  });

  test('the payload round-trips through the app\'s own re-serialisation',
      () async {
    // Dio decodes the body before the repository sees it, so the original bytes
    // are gone and the app must rebuild them. This is the assertion that the
    // rebuild is faithful.
    final rebuilt = canonicalise(
      Map<String, dynamic>.from(jsonDecode(canonical) as Map),
    );
    expect(await verify(rebuilt, signatureHex, publicKeyHex), isTrue);
  });

  group('what must fail', () {
    test('a payload edited on the device', () async {
      // The child's move: extend the subscription by a month in the local
      // database. Art. 7.6 exists for exactly this.
      final tampered = Map<String, dynamic>.from(payload)
        ..['ends_at_ms'] = 1778403600000;
      expect(
        await verify(canonicalise(tampered), signatureHex, publicKeyHex),
        isFalse,
      );
    });

    test('a state promoted from expired to active', () async {
      final tampered = Map<String, dynamic>.from(payload)..['state'] = 'trial';
      expect(
        await verify(canonicalise(tampered), signatureHex, publicKeyHex),
        isFalse,
      );
    });

    test('a snapshot signed by somebody else\'s key', () async {
      final other = await Ed25519().newKeyPair();
      final theirs = await Ed25519().sign(
        utf8.encode(canonical),
        keyPair: other,
      );
      expect(
        await Ed25519().verify(
          utf8.encode(canonical),
          signature: Signature(
            theirs.bytes,
            publicKey: SimplePublicKey(
              [
                for (var i = 0; i < publicKeyHex.length; i += 2)
                  int.parse(publicKeyHex.substring(i, i + 2), radix: 16),
              ],
              type: KeyPairType.ed25519,
            ),
          ),
        ),
        isFalse,
        reason: 'the embedded public key is the only thing that makes a '
            'signature mean anything — a key taken from the response would be '
            'circular',
      );
    });

    test('a signature with one byte changed', () async {
      final broken = '${signatureHex.substring(0, signatureHex.length - 2)}ff';
      expect(await verify(canonical, broken, publicKeyHex), isFalse);
    });

    test('whitespace added to the canonical form', () async {
      const spaced =
          '{"ends_at_ms": 1775725200000, "grace_ends_at_ms": 1775984400000, '
          '"issued_at_ms": 1773133200000, "parent_id": 7, "plan": "monthly", '
          '"started_at_ms": 1773133200000, "state": "active", "version": 1}';
      expect(await verify(spaced, signatureHex, publicKeyHex), isFalse,
          reason: 'this is the failure the canonicalisation test above exists '
              'to catch before it reaches a real device');
    });
  });
}
